From a38978ab46f568e8aa6316c875efc91d930042b5 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 02:15:40 +0100
Subject: [PATCH] declarativeimports/core: show tooltip at once if another just
 closed

Moving between task manager icons, the triangle filter can hold back the
next icon's hover enter until the old tooltip has closed, so the new one
waited the full delay. Now it shows at once if one closed under 500 ms.

BUG: 513390
---
 src/declarativeimports/core/tooltiparea.cpp   | 4 ++++
 src/declarativeimports/core/tooltipdialog.cpp | 7 +++++++
 src/declarativeimports/core/tooltipdialog.h   | 7 +++++++
 3 files changed, 18 insertions(+)

diff --git a/src/declarativeimports/core/tooltiparea.cpp b/src/declarativeimports/core/tooltiparea.cpp
index 41e346e4c..5da5dd7bd 100644
--- a/src/declarativeimports/core/tooltiparea.cpp
+++ b/src/declarativeimports/core/tooltiparea.cpp
@@ -382,6 +382,10 @@ void ToolTipArea::hoverEnterEvent(QHoverEvent *event)
                 showToolTip();
             }
         }
+    } else if (m_active && tooltipDialogInstance()->recentlyDismissed()) {
+        // Moving between items, e.g. with a TriangleMouseFilter holding back
+        // this hover enter: don't make the user wait for the full delay again
+        showToolTip();
     } else {
         m_showTimer.start(m_interval);
     }
diff --git a/src/declarativeimports/core/tooltipdialog.cpp b/src/declarativeimports/core/tooltipdialog.cpp
index 73b7675df..eb8141ed1 100644
--- a/src/declarativeimports/core/tooltipdialog.cpp
+++ b/src/declarativeimports/core/tooltipdialog.cpp
@@ -33,6 +33,7 @@ ToolTipDialog::ToolTipDialog()
     m_hideTimer.setSingleShot(true);
     connect(&m_hideTimer, &QTimer::timeout, this, [this]() {
         setVisible(false);
+        m_dismissedTimer.start();
     });

     connect(this, &PlasmaQuick::PlasmaWindow::mainItemChanged, this, [this]() {
@@ -80,6 +81,7 @@ QQuickItem *ToolTipDialog::loadDefaultItem()

 void ToolTipDialog::showEvent(QShowEvent *event)
 {
+    m_dismissedTimer.invalidate();
     keepalive();

     PlasmaQuick::PopupPlasmaWindow::showEvent(event);
@@ -121,6 +123,11 @@ void ToolTipDialog::dismiss()
     m_hideTimer.start(200);
 }

+bool ToolTipDialog::recentlyDismissed() const
+{
+    return m_dismissedTimer.isValid() && m_dismissedTimer.elapsed() < 500;
+}
+
 void ToolTipDialog::keepalive()
 {
     if (m_hideTimeout > 0) {
diff --git a/src/declarativeimports/core/tooltipdialog.h b/src/declarativeimports/core/tooltipdialog.h
index 3af03f556..af09d70cf 100644
--- a/src/declarativeimports/core/tooltipdialog.h
+++ b/src/declarativeimports/core/tooltipdialog.h
@@ -9,6 +9,7 @@

 #include "popupplasmawindow.h"

+#include <QElapsedTimer>
 #include <QQuickWindow>
 #include <QTimer>
 #include <QVariant>
@@ -31,6 +32,11 @@ public:
     void dismiss();
     void keepalive();

+    /*!
+     * Whether the dialog was hidden by its hide timer a moment ago
+     */
+    bool recentlyDismissed() const;
+
     bool interactive();
     void setInteractive(bool interactive);

@@ -58,6 +64,7 @@ private:
     std::shared_ptr<QQmlEngine> m_engine;
     std::unique_ptr<QQuickItem> m_qmlObject = nullptr;
     QTimer m_hideTimer;
+    QElapsedTimer m_dismissedTimer;
     int m_hideTimeout;
     bool m_interactive;
     QObject *m_owner;
